function validate([n, mines]) {
  if (!Number.isInteger(n) || n < 1 || n > 500) return 'n is an integer from 1 to 500.';
  if (!Array.isArray(mines) || mines.length < 1 || mines.length > 5000) return 'mines needs 1 to 5000 cells.';
  const seen = new Set();
  for (const cell of mines) {
    if (!Array.isArray(cell) || cell.length !== 2 || !cell.every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'Each mine is [row, column] inside the grid.';
    const key = cell[0] * n + cell[1];
    if (seen.has(key)) return 'Each mine must be a different cell.';
    seen.add(key);
  }
  return null;
}

