function orderOfLargestPlusSign(n, mines) {
  const grid = Array.from({ length: n }, () => new Array(n).fill(1));
  for (const [r, c] of mines) {
    grid[r][c] = 0;
  }
  const dp = Array.from({ length: n }, () => new Array(n).fill(n));

  for (let r = 0; r < n; r++) {
    let run = 0;
    for (let c = 0; c < n; c++) {
      run = grid[r][c] === 1 ? run + 1 : 0;
      dp[r][c] = Math.min(dp[r][c], run);
    }
    run = 0;
    for (let c = n - 1; c >= 0; c--) {
      run = grid[r][c] === 1 ? run + 1 : 0;
      dp[r][c] = Math.min(dp[r][c], run);
    }
  }
  for (let c = 0; c < n; c++) {
    let run = 0;
    for (let r = 0; r < n; r++) {
      run = grid[r][c] === 1 ? run + 1 : 0;
      dp[r][c] = Math.min(dp[r][c], run);
    }
    run = 0;
    for (let r = n - 1; r >= 0; r--) {
      run = grid[r][c] === 1 ? run + 1 : 0;
      dp[r][c] = Math.min(dp[r][c], run);
    }
  }

  let best = 0;
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      best = Math.max(best, dp[r][c]);
    }
  }
  return best;
}

