function orderOfLargestPlusSign(n, mines) {
  const open = Array.from({ length: n }, () => new Array(n).fill(true));
  for (const [x, y] of mines) open[x][y] = false;
  const one = (x, y) => x >= 0 && y >= 0 && x < n && y < n && open[x][y];
  let best = 0;
  for (let x = 0; x < n; x++)
    for (let y = 0; y < n; y++) {
      let k = 0;
      while (one(x - k, y) && one(x + k, y) && one(x, y - k) && one(x, y + k)) k++;
      best = Math.max(best, k);
    }
  return best;
}

