function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let n, count;
  if (size === 'small') {
    n = int(1, 8);
    count = int(1, Math.min(n * n, rand() < 0.5 ? 3 : n * n));
  } else {
    n = int(300, 500);
    const style = int(0, 2);
    count = style === 0 ? int(1, 20) : style === 1 ? int(200, 1000) : int(1500, 2000);
  }
  const used = new Set(), mines = [];
  while (mines.length < count) {
    const x = int(0, n - 1), y = int(0, n - 1);
    if (used.has(x * n + y)) continue;
    used.add(x * n + y);
    mines.push([x, y]);
  }
  return [n, mines];
}
